def verifier(assign):
    # Recompute the target value and answer exactly; validate domain constraints.
    from fractions import Fraction

    # Basic presence checks
    required = ['scale', 'lower', 'upper', 'a', 'b', 'c', 'd']
    for k in required:
        if k not in assign:
            # Missing slot
            return False, None  # missing key
    scale = assign['scale']; lower = assign['lower']; upper = assign['upper']
    a = assign['a']; b = assign['b']; c = assign['c']; d = assign['d']

    # Type and domain checks
    if not all(isinstance(x, int) for x in [scale, lower, upper, a, b, c, d]):
        return False, None  # types must be int
    if scale < 100:
        return False, None  # scale too small -> trivial rounding
    if upper <= lower:
        return False, None  # invalid range
    if upper - lower < 500:
        return False, None  # enforce difficulty
    if c < 1 or d < 2 or not (c < d):
        return False, None  # poles invalid
    if lower < d + 1:
        return False, None  # range must avoid singularities at n=d and n=c
    if a == 0:
        return False, None  # avoids degenerate seed-like case
    if b == a * c or b == -a * c:
        return False, None  # avoids vanishing residues at c

    # Partial fractions residues
    A_c = Fraction(a, 2) + Fraction(b, 2 * c)
    B_c = Fraction(a, 2) - Fraction(b, 2 * c)
    A_d = Fraction(a, 2) + Fraction(b, 2 * d)
    B_d = Fraction(a, 2) - Fraction(b, 2 * d)
    if A_c == 0 or B_c == 0 or A_d == 0 or B_d == 0:
        return False, None  # degeneracy forbidden

    # Harmonic-range helper (lo>=1 guaranteed by lower>=d+1>c)
    def H_range(lo, hi):
        s = Fraction(0, 1)
        for m in range(lo, hi + 1):
            if m == 0:
                return False, None  # zero denominator would occur (shouldn't)
            s += Fraction(1, m)
        return s

    # Compute S
    term_c = A_c * H_range(lower - c, upper - c) + B_c * H_range(lower + c, upper + c)
    term_d = A_d * H_range(lower - d, upper - d) + B_d * H_range(lower + d, upper + d)
    S = term_c - term_d

    # Final value
    val = Fraction(scale, 1) * S

    # Nearest integer with tie check
    num, den = val.numerator, val.denominator
    q = num // den
    r = num - q * den
    if r * 2 == den:
        return False, None  # exact halfway tie not allowed
    ans = q if r * 2 < den else q + 1

    # Additional difficulty checks: avoid exact integer value
    if num % den == 0:
        return False, None

    return True, ans
